import { useEffect, useRef, useState } from "react";
import { nf } from "./data";

interface SyncStatus {
  enabled: boolean;
  listening: boolean;
  error: string | null;
  url: string | null;
  port: number;
  folder: string;
  layout: "month" | "flat";
  /** Why files can't be saved to the folder (only possible in Docker). */
  folderError: string | null;
  defaultFolder: string;
  inDocker: boolean;
  /** In Docker, the folders shared from the computer that a sync folder can go in. */
  dockerFolders: string[];
  /** SVG markup of the pairing code, generated by the server from its own address and token. */
  qr: string | null;
  files: number;
  last: number | null;
}

async function call(url: string, body?: unknown): Promise<SyncStatus> {
  const r = await fetch(url, {
    method: body === undefined ? "GET" : "POST",
    headers: body === undefined ? undefined : { "content-type": "application/json" },
    body: body === undefined ? undefined : JSON.stringify(body),
  });
  const j = await r.json();
  if (!r.ok) throw new Error(j.error ?? r.statusText);
  return j as SyncStatus;
}

/** Where synced files go, and a way to change it. */
function SyncFolder({ status, onChange }: { status: SyncStatus; onChange(s: SyncStatus): void }) {
  const [editing, setEditing] = useState(false);
  const [path, setPath] = useState("");
  const [error, setError] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);
  const [moved, setMoved] = useState(false);

  const save = async (next: { path?: string | null; layout?: SyncStatus["layout"] }) => {
    setBusy(true);
    setError(null);
    try {
      const s = await call("/api/sync/folder", next);
      if (s.folder !== status.folder) setMoved(status.files > 0);
      onChange(s);
      setEditing(false);
    } catch (err) {
      setError((err as Error).message);
    } finally {
      setBusy(false);
    }
  };

  if (!editing) {
    return (
      <div className="sync-folder-box">
        <div className="dim small">Saves into</div>
        <div className="row">
          <span className="mono small break sync-folder">{status.folder}</span>
          <button
            className="btn btn-small"
            onClick={() => {
              setPath(status.folder);
              setError(null);
              setEditing(true);
            }}
          >
            Change
          </button>
        </div>
        <div className="segmented" role="group" aria-label="Folder layout">
          {(
            [
              ["month", "Year/month folders"],
              ["flat", "All in this folder"],
            ] as const
          ).map(([value, label]) => (
            <button
              key={value}
              type="button"
              aria-pressed={status.layout === value}
              disabled={busy}
              onClick={() => status.layout !== value && save({ layout: value })}
            >
              {label}
            </button>
          ))}
        </div>
        <div className="dim small">
          Added to the library and scanned as files arrive. Photos already in the library, by name and time, aren't sent
          again.
          {moved && " Files received before stay in the previous folder."}
        </div>
        {status.folderError && <div className="error">{status.folderError}</div>}
        {error && <div className="error">{error}</div>}
      </div>
    );
  }

  return (
    <form
      className="sync-folder-box"
      onSubmit={(e) => {
        e.preventDefault();
        if (path.trim()) void save({ path: path.trim() });
      }}
    >
      <div className="row">
        <input
          className="input mono"
          value={path}
          onChange={(e) => setPath(e.target.value)}
          placeholder="~/Pictures/Phone"
          autoFocus
          spellCheck={false}
          aria-label="Sync folder"
        />
        <button className="btn btn-primary" disabled={busy || !path.trim()}>
          Save
        </button>
        <button type="button" className="btn btn-ghost" onClick={() => setEditing(false)}>
          Cancel
        </button>
      </div>
      {status.inDocker && status.dockerFolders.length > 0 && (
        <div className="dim small">
          Photomap runs in Docker, so the folder must be inside{" "}
          {status.dockerFolders.map((f, i) => (
            <span key={f}>
              {i > 0 && " or "}
              <span className="mono">{f}</span>
            </span>
          ))}
          .
        </div>
      )}
      {status.folder !== status.defaultFolder && (
        <button type="button" className="btn btn-small btn-ghost" disabled={busy} onClick={() => save({ path: null })}>
          Use the default, {status.defaultFolder}
        </button>
      )}
      {error && <div className="error">{error}</div>}
    </form>
  );
}

/** The Library's phone sync section: a switch, and the code the Photomap Sync app scans. */
export function SyncSection({ onReceived }: { onReceived(): void }) {
  const [status, setStatus] = useState<SyncStatus | null>(null);
  const [error, setError] = useState<string | null>(null);
  const received = useRef(onReceived);
  received.current = onReceived;

  useEffect(() => {
    let files: number | null = null;
    const load = () =>
      call("/api/sync")
        .then((s) => {
          if (files !== null && s.files !== files) received.current();
          files = s.files;
          setStatus(s);
        })
        .catch((err) => setError((err as Error).message));
    load();
    // Count the files arriving while the drawer is open.
    const t = setInterval(load, 4000);
    return () => clearInterval(t);
  }, []);

  const act = (url: string, body?: unknown) =>
    call(url, body ?? {})
      .then((s) => {
        setStatus(s);
        setError(null);
      })
      .catch((err) => setError((err as Error).message));

  const reset = () => {
    if (!confirm("Unpair every phone? Each one will need to scan the new code before it can sync again.")) return;
    void act("/api/sync/reset");
  };

  if (!status) return null;

  return (
    <section>
      <h4>Phone sync</h4>
      <p className="dim small">
        The Photomap Sync app sends your phone's photos and videos here over wifi, with their locations.
      </p>
      <SyncFolder status={status} onChange={setStatus} />
      <label className="row sync-toggle">
        <input
          type="checkbox"
          checked={status.enabled}
          onChange={(e) => act("/api/sync", { enabled: e.target.checked })}
        />
        <span>Accept phones on this network</span>
      </label>
      {status.error && (
        <div className="error">
          Couldn't listen on port {status.port}: {status.error}
        </div>
      )}
      {error && <div className="error">{error}</div>}

      {status.enabled && status.listening && (
        <>
          {status.qr ? (
            <div className="sync-pair">
              <div className="sync-qr" dangerouslySetInnerHTML={{ __html: status.qr }} />
              <div className="small">
                <p>Open Photomap Sync on your phone and tap Scan pairing code.</p>
                <p className="dim">
                  The phone must be on the same wifi. It connects to <span className="mono">{status.url}</span>.
                </p>
              </div>
            </div>
          ) : (
            <div className="error">
              {status.inDocker
                ? "Inside Docker, Photomap can't tell your computer's network address."
                : "No local network address found. Is this computer on wifi or ethernet?"}{" "}
              Set <span className="mono">PHOTOMAP_SYNC_URL</span> to e.g.{" "}
              <span className="mono">http://192.168.1.20:{status.port}</span> and restart.
            </div>
          )}
          <p className="dim small">
            {status.files > 0
              ? `${nf.format(status.files)} ${status.files === 1 ? "file" : "files"} received, last ${new Date(status.last!).toLocaleString()}`
              : "Nothing received yet."}{" "}
            <button className="btn btn-small btn-ghost" onClick={reset}>
              Unpair all phones
            </button>
          </p>
        </>
      )}
    </section>
  );
}
